export const MODULES = {"shared/seed.js":"/* The daily seed, shared by every Arcade Lab game, browser and server alike.\n *\n * The day is the calendar date in America/New_York, so the daily turns over at\n * midnight Eastern for everybody. seed = fnv1a(dateKey + '|' + gameId), and all\n * randomness in a sim comes from mulberry32 off that seed. Nothing here may call\n * Math.random: the server replays a run from its input log and has to land on\n * exactly the number the player saw.\n */\nexport const TIME_ZONE = 'America/New_York';\n/* Daily #1 is this Eastern date. Only used for the number on the share line. */\nexport const EPOCH = '2026-10-10';\n\nexport function dateKey(nowMs) {\n  const p = new Intl.DateTimeFormat('en-CA', { timeZone: TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit' })\n    .formatToParts(new Date(nowMs));\n  const g = t => p.find(x => x.type === t).value;\n  return g('year') + '-' + g('month') + '-' + g('day');\n}\n\n/* Day arithmetic in UTC on the date itself, so a clock change cannot floor\n   two midnights into the wrong day. */\nexport function dayNumber(key) {\n  const d = (s) => Date.UTC(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10));\n  return Math.round((d(key) - d(EPOCH)) / 86400000) + 1;\n}\n\nexport function prevDateKey(key) {\n  const t = Date.UTC(+key.slice(0, 4), +key.slice(5, 7) - 1, +key.slice(8, 10)) - 86400000;\n  return new Date(t).toISOString().slice(0, 10);\n}\n\n/* Milliseconds until the next Eastern midnight, for the countdown. */\nexport function msToNextDay(nowMs) {\n  const today = dateKey(nowMs);\n  let lo = nowMs, hi = nowMs + 26 * 3600000;\n  while (hi - lo > 1000) { const mid = Math.floor((lo + hi) / 2); if (dateKey(mid) === today) lo = mid; else hi = mid; }\n  return hi - nowMs;\n}\n\nexport function hashStr(s) {\n  let h = 0x811c9dc5;\n  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }\n  return h >>> 0;\n}\n\nexport function seedFor(key, gameId) { return hashStr(key + '|' + gameId); }\n\nexport function mulberry32(a) {\n  a = a >>> 0;\n  return function () {\n    a = (a + 0x6D2B79F5) >>> 0;\n    let t = a;\n    t = Math.imul(t ^ (t >>> 15), t | 1);\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\n/* A stream keyed to one throw, so ball 4 lands the same way whatever balls\n   1 to 3 did. */\nexport function streamFor(seed, tag) { return mulberry32((seed ^ hashStr(String(tag))) >>> 0); }\n","shared/gems.js":"/* Gems: the Arcade Lab's cosmetic currency. They have NO cash value and can\n * never be redeemed for money. Every game pays the same shape: 5 for finishing\n * the daily, plus a bonus by score band (up to 10 more). Practice pays 0.\n *\n * bands: ascending list of { min, bonus }. The highest band whose min the\n * score reaches is the bonus. */\nexport const GEMS_FOR_DAILY = 5;\nexport const GEMS_BONUS_MAX = 10;\n\nexport function gemsFor(score, bands) {\n  let bonus = 0;\n  for (const b of bands) if (score >= b.min) bonus = b.bonus;\n  return GEMS_FOR_DAILY + Math.min(GEMS_BONUS_MAX, bonus);\n}\n","shared/share.js":"/* The share line every Arcade Lab game uses: a header, one strip of squares,\n * the url. No spoilers: the squares say how it went, never where. */\nexport const SHARE_URL = 'https://runthe.gg/arcade/';\nexport function shareText(name, dayNo, score, squares) {\n  return name + ' #' + dayNo + ' ' + score + '\\n' + squares.join('') + '\\n' + SHARE_URL;\n}\n","shared/kit.js":"/* The browser half every Arcade Lab game shares: the API, the guest id, the\n * session, sound, haptics, the share sheet, the countdown and the host\n * character hook. Nothing here decides a score. */\nimport { msToNextDay } from './seed.js';\n\nconst LS = (() => { try { return window.localStorage; } catch (e) { return null; } })();\nexport function lsGet(k, d) { try { const v = LS && LS.getItem(k); return v == null ? d : v; } catch (e) { return d; } }\nexport function lsSet(k, v) { try { LS && LS.setItem(k, v); } catch (e) {} }\n\nconst GUEST_KEY = 'arcade_lab_guest_v1';\nexport function guestId() {\n  let g = lsGet(GUEST_KEY, null);\n  if (!g) {\n    const b = new Uint8Array(16); crypto.getRandomValues(b);\n    g = Array.from(b, x => x.toString(16).padStart(2, '0')).join('');\n    lsSet(GUEST_KEY, g);\n  }\n  return g;\n}\n\n/* The session: resolves once auth.js has said who this is (or that it cannot). */\nexport function session() {\n  const A = window.RTG_AUTH;\n  return new Promise(res => {\n    if (!A || !A.boot || !A.boot()) return res({ signedIn: false });\n    let done = false;\n    const t = setTimeout(() => { if (!done) { done = true; res({ signedIn: false }); } }, 4000);\n    A.onChange(s => { if (done || !s || !s.resolved) return; done = true; clearTimeout(t); res(s); });\n  });\n}\n\nexport async function api(method, path, body) {\n  const h = { 'Content-Type': 'application/json', 'X-Arcade-Guest': guestId() };\n  const A = window.RTG_AUTH, t = A && A.token && A.token();\n  if (t) h.Authorization = 'Bearer ' + t;\n  const r = await fetch('/api/arcade/' + path, { method, headers: h, body: body ? JSON.stringify(body) : undefined, credentials: 'same-origin' });\n  let data = null; try { data = await r.json(); } catch (e) {}\n  return { status: r.status, data };\n}\n\n/* Sound: effects only, synthesized, silent until the first tap, and a toggle\n   that is remembered. */\nexport function makeSound() {\n  let ctx = null, unlocked = false, muted = lsGet('arcade_lab_mute', '0') === '1';\n  function unlock() {\n    if (unlocked) return; unlocked = true;\n    try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { ctx = null; }\n  }\n  function tone(f, dur, type, vol, slide) {\n    if (!ctx || muted) return;\n    const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();\n    o.type = type || 'sine'; o.frequency.setValueAtTime(f, t);\n    if (slide) o.frequency.exponentialRampToValueAtTime(slide, t + dur);\n    g.gain.setValueAtTime(vol || 0.15, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);\n    o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + dur + 0.02);\n  }\n  function noise(dur, vol) {\n    if (!ctx || muted) return;\n    const n = Math.floor(ctx.sampleRate * dur), b = ctx.createBuffer(1, n, ctx.sampleRate), d = b.getChannelData(0);\n    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);\n    const s = ctx.createBufferSource(), g = ctx.createGain(); g.gain.value = vol || 0.08;\n    s.buffer = b; s.connect(g).connect(ctx.destination); s.start();\n  }\n  return {\n    unlock, get muted() { return muted; },\n    toggle() { muted = !muted; lsSet('arcade_lab_mute', muted ? '1' : '0'); return muted; },\n    play(name) {\n      if (name === 'roll') noise(0.35, 0.05);\n      else if (name === 'launch') tone(300, 0.18, 'triangle', 0.08, 520);\n      else if (name === 'land') tone(140, 0.12, 'square', 0.08, 90);\n      else if (name === 'rail') tone(220, 0.06, 'square', 0.05);\n      else if (name === 'good') { tone(523, 0.12, 'triangle', 0.12); setTimeout(() => tone(784, 0.18, 'triangle', 0.12), 90); }\n      else if (name === 'big') { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => tone(f, 0.16, 'square', 0.08), i * 80)); }\n      else if (name === 'foul') tone(160, 0.3, 'sawtooth', 0.07, 80);\n    }\n  };\n}\n\nexport function makeHaptics() {\n  let on = lsGet('arcade_lab_haptics', '1') === '1';\n  return {\n    get on() { return on; },\n    toggle() { on = !on; lsSet('arcade_lab_haptics', on ? '1' : '0'); return on; },\n    buzz(p) { if (on && navigator.vibrate) { try { navigator.vibrate(p); } catch (e) {} } }\n  };\n}\n\n/* The host character hook. The art comes later; anything that wants to draw\n   the host reads window.ARCADE_HOST or the element's data attributes. */\nexport function makeHost(el) {\n  const st = { mood: 'idle', state: 'idle' };\n  window.ARCADE_HOST = st;\n  function set(mood, state) {\n    st.mood = mood; st.state = state || mood;\n    if (el) { el.dataset.mood = st.mood; el.dataset.state = st.state; }\n  }\n  set('idle');\n  return { set, get: () => ({ ...st }) };\n}\n\nexport async function share(text) {\n  if (navigator.share) { try { await navigator.share({ text }); return 'shared'; } catch (e) { if (e && e.name === 'AbortError') return 'cancelled'; } }\n  try { await navigator.clipboard.writeText(text); return 'copied'; } catch (e) { return 'failed'; }\n}\n\nexport function countdown(el) {\n  function tick() {\n    const ms = msToNextDay(Date.now()), s = Math.floor(ms / 1000);\n    const h = Math.floor(s / 3600), m = Math.floor(s / 60) % 60, x = s % 60;\n    el.textContent = h + ':' + String(m).padStart(2, '0') + ':' + String(x).padStart(2, '0');\n  }\n  tick(); return setInterval(tick, 1000);\n}\n\nexport const reducedMotion = () => !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);\n","games/rollball/config.js":"/* Roll-Ball: every feel-tuning number in ONE place.\n *\n * World units are centimetres-ish on a top-down lane. x runs left to right,\n * 0 is the middle of the lane. y runs away from the player: the ball starts at\n * y 0, the ramp lip is at LIP_Y, the target board sits beyond it.\n * Time is fixed-step frames of 1/60 s. Nothing reads the wall clock.\n */\nexport const CONFIG = Object.freeze({\n  GAME_ID: 'roll-ball',\n  NAME: 'Roll-Ball',\n  DT: 1 / 60,\n  BALLS: 9,\n  MAX_BASES: 4,                // a ball never scores more than a home run\n\n  /* The throw. Power 0..1 maps linearly to launch speed. */\n  V_MIN: 120,                  // units/s at power 0\n  V_MAX: 330,                  // units/s at power 1\n  MAX_ANGLE: 0.42,             // radians either side of straight up the lane\n\n  /* The lane. */\n  LANE_HALF: 28,               // half width of the lane between its rails\n  LANE_FRICTION: 55,           // deceleration on the lane, units/s^2\n  WALL_E: 0.55,                // speed kept across a rail bounce\n  LIP_Y: 170,                  // the ramp lip; past it the ball is airborne\n  MIN_LIP_SPEED: 70,           // slower than this at the lip and it rolls back: foul\n\n  /* The flight. Carry is speed at the lip times CARRY_S, then jittered. */\n  FLIGHT_FRAMES: 32,           // fixed airtime, so the arc reads the same every throw\n  CARRY_S: 0.55,               // seconds of carry per unit of lip speed\n  CARRY_JITTER: 0.035,         // +/- share of the carry, seeded per ball\n  ANGLE_JITTER: 0.012,         // +/- radians at the lip, seeded per ball\n  ARC_HEIGHT: 38,              // peak height of the arc, for drawing only\n\n  /* The board after landing. */\n  ROLL_KEEP: 0.18,             // share of the speed kept after the landing\n  BOARD_FRICTION: 170,         // deceleration on the board, units/s^2\n  BOARD_HALF: 60,              // the side gutters start past this\n  BOARD_FRONT: 196,            // the bottom lip: landing short of it is foul\n  BOARD_BACK: 336,             // the back gutter\n  EDGE_BAND: 1.6,              // a rest this close to a ring line can hop\n  HOP: 2.6,                    // how far a hop moves it off the line\n  POCKET_R: 7,                 // home run pocket radius\n  SETTLE_FRAMES: 40,           // the pause on a result before the next ball\n\n  /* Scoring. Max is BALLS * MAX_BASES = 36. */\n  BASES: Object.freeze({ '1B': 1, '2B': 2, '3B': 3, HR: 4, F: 0 }),\n  HOT_BONUS: 1,\n\n  /* Gems bonus by score band (5 for finishing is added by shared/gems.js). */\n  GEM_BANDS: Object.freeze([{ min: 0, bonus: 0 }, { min: 12, bonus: 3 }, { min: 20, bonus: 6 }, { min: 28, bonus: 10 }]),\n\n  /* The server refuses a log longer than this (30 minutes of frames). */\n  MAX_FRAMES: 60 * 60 * 30\n});\n\n/* Eight layouts. A day picks one, then a hot ring. Ring radii are single,\n   double, triple. A pocket with `slide` moves side to side on a sine:\n   amplitude in units, period in frames, phase 0 or 0.5. */\nconst P = (x, y, slide) => ({ x, y, slide: slide || null });\nexport const LAYOUTS = Object.freeze([\n  { id: 'classic',  name: 'Classic board', ring: { x: 0, y: 262, r: [52, 20, 6.5] }, pockets: [P(-36, 308), P(36, 308)] },\n  { id: 'lean-l',   name: 'Leaning left',  ring: { x: -6, y: 262, r: [52, 20, 6.5] }, pockets: [P(-42, 306), P(32, 310)] },\n  { id: 'lean-r',   name: 'Leaning right', ring: { x: 6, y: 262, r: [52, 20, 6.5] }, pockets: [P(-32, 310), P(42, 306)] },\n  { id: 'deep',     name: 'Deep board',    ring: { x: 0, y: 270, r: [50, 19, 6] }, pockets: [P(-34, 316), P(34, 316)] },\n  { id: 'shallow',  name: 'Short board',   ring: { x: 0, y: 252, r: [52, 20, 6.5] }, pockets: [P(-38, 298), P(38, 298)] },\n  { id: 'slide-l',  name: 'Moving left pocket',  ring: { x: 0, y: 262, r: [52, 20, 6.5] },\n    pockets: [P(-36, 309, { amp: 10, period: 220, phase: 0 }), P(36, 308)] },\n  { id: 'slide-r',  name: 'Moving right pocket', ring: { x: 0, y: 262, r: [52, 20, 6.5] },\n    pockets: [P(-36, 308), P(36, 309, { amp: 10, period: 220, phase: 0.5 })] },\n  { id: 'twins',    name: 'Twin sliders',  ring: { x: 0, y: 263, r: [51, 19, 6] },\n    pockets: [P(-36, 310, { amp: 8, period: 260, phase: 0 }), P(36, 310, { amp: 8, period: 260, phase: 0.5 })] }\n]);\nexport const HOT_ZONES = Object.freeze(['1B', '2B', '3B']);\n","games/rollball/sim.js":"/* Roll-Ball: the rules as a pure, fixed-step simulation.\n *\n * No DOM, no wall clock, no Math.random. The browser steps it at 60 Hz and the\n * server replays the same input log through the same code, so the score the\n * player saw is the score the server records, and a forged one does not match.\n *\n * An input is { f, a, p }: at the start of frame f, throw at angle a\n * (radians, 0 is straight) with power p (0..1). A throw is only legal while\n * the phase is 'ready'.\n */\nimport { CONFIG as C, LAYOUTS, HOT_ZONES } from './config.js';\nimport { mulberry32, streamFor } from '../../shared/seed.js';\nimport { gemsFor } from '../../shared/gems.js';\n\nexport const GAME_ID = C.GAME_ID;\nexport const NAME = C.NAME;\n\n/* What a seed means for the day: the board and the hot ring. */\nexport function dailyConfig(seed) {\n  const r = mulberry32(seed);\n  const layout = LAYOUTS[Math.floor(r() * LAYOUTS.length)];\n  const hot = HOT_ZONES[Math.floor(r() * HOT_ZONES.length)];\n  return { layoutId: layout.id, hot, rule: ruleLine(layout, hot) };\n}\n\nconst ZONE_WORD = { '1B': 'Single', '2B': 'Double', '3B': 'Triple' };\nexport function ruleLine(layout, hot) {\n  const slides = layout.pockets.filter(p => p.slide).length;\n  const mover = slides === 2 ? ' Both pockets slide.' : slides === 1 ? ' One home run pocket slides.' : '';\n  return layout.name + '. The ' + ZONE_WORD[hot] + ' ring is hot for +1 base.' + mover;\n}\n\nexport function layoutOf(id) { return LAYOUTS.find(l => l.id === id) || LAYOUTS[0]; }\n\n/* Where a pocket is on a given frame. */\nexport function pocketAt(p, frame) {\n  if (!p.slide) return { x: p.x, y: p.y };\n  const t = frame / p.slide.period + p.slide.phase;\n  return { x: p.x + p.slide.amp * Math.sin(2 * Math.PI * t), y: p.y };\n}\n\nexport function create(seed) {\n  const day = dailyConfig(seed);\n  return {\n    seed, day, layout: layoutOf(day.layoutId), frame: 0,\n    ball: 0, phase: 'ready', phaseFrame: 0,\n    x: 0, y: 0, z: 0, vx: 0, vy: 0,\n    air: null, results: [], score: 0, over: false, event: null\n  };\n}\n\n/* Throw the current ball. Returns false (and changes nothing) if not legal. */\nexport function throwBall(s, a, p) {\n  if (s.phase !== 'ready' || s.over) return false;\n  if (!(typeof a === 'number' && isFinite(a) && Math.abs(a) <= C.MAX_ANGLE + 1e-9)) return false;\n  if (!(typeof p === 'number' && isFinite(p) && p >= 0 && p <= 1)) return false;\n  const v = C.V_MIN + p * (C.V_MAX - C.V_MIN);\n  s.x = 0; s.y = 0; s.z = 0;\n  s.vx = v * Math.sin(a); s.vy = v * Math.cos(a);\n  s.phase = 'lane'; s.phaseFrame = 0;\n  return true;\n}\n\nfunction decel(s, a) {\n  const sp = Math.hypot(s.vx, s.vy);\n  if (sp === 0) return 0;\n  const ns = Math.max(0, sp - a * C.DT);\n  s.vx *= ns / sp; s.vy *= ns / sp;\n  return ns;\n}\n\nfunction ringZone(L, x, y) {\n  const d = Math.hypot(x - L.ring.x, y - L.ring.y);\n  const [r1, r2, r3] = L.ring.r;\n  return d <= r3 ? '3B' : d <= r2 ? '2B' : d <= r1 ? '1B' : 'F';\n}\n\nfunction finish(s, zone, why) {\n  const base = C.BASES[zone];\n  const hot = zone === s.day.hot;\n  const bases = Math.min(C.MAX_BASES, base + (hot ? C.HOT_BONUS : 0));\n  s.results.push({ zone, bases, hot, why: why || null });\n  s.score += bases;\n  s.phase = 'settle'; s.phaseFrame = 0;\n  s.vx = s.vy = 0; s.z = 0;\n  s.event = { type: 'result', zone, bases, hot, ball: s.ball };\n}\n\n/* Advance one fixed step. */\nexport function step(s) {\n  s.event = null;\n  s.frame++;\n  s.phaseFrame++;\n  const L = s.layout;\n  if (s.phase === 'lane') {\n    decel(s, C.LANE_FRICTION);\n    s.x += s.vx * C.DT; s.y += s.vy * C.DT;\n    if (s.x > C.LANE_HALF) { s.x = 2 * C.LANE_HALF - s.x; s.vx = -Math.abs(s.vx) * C.WALL_E; s.vy *= C.WALL_E + (1 - C.WALL_E) * 0.6; s.event = { type: 'rail' }; }\n    if (s.x < -C.LANE_HALF) { s.x = -2 * C.LANE_HALF - s.x; s.vx = Math.abs(s.vx) * C.WALL_E; s.vy *= C.WALL_E + (1 - C.WALL_E) * 0.6; s.event = { type: 'rail' }; }\n    if (s.vy <= 0) return finish(s, 'F', 'short');\n    if (s.y >= C.LIP_Y) {\n      const sp = Math.hypot(s.vx, s.vy);\n      if (sp < C.MIN_LIP_SPEED) return finish(s, 'F', 'short');\n      const r = streamFor(s.seed, 'ball' + s.ball);\n      const jc = (r() * 2 - 1) * C.CARRY_JITTER, ja = (r() * 2 - 1) * C.ANGLE_JITTER;\n      const ang = Math.atan2(s.vx, s.vy) + ja;\n      const carry = sp * C.CARRY_S * (1 + jc);\n      s.air = { x0: s.x, y0: s.y, x1: s.x + carry * Math.sin(ang), y1: s.y + carry * Math.cos(ang), sp, ang, hop: r() };\n      s.phase = 'air'; s.phaseFrame = 0;\n      s.event = { type: 'launch' };\n    }\n    return;\n  }\n  if (s.phase === 'air') {\n    const A = s.air, t = s.phaseFrame / C.FLIGHT_FRAMES;\n    s.x = A.x0 + (A.x1 - A.x0) * t; s.y = A.y0 + (A.y1 - A.y0) * t;\n    s.z = C.ARC_HEIGHT * 4 * t * (1 - t);\n    if (s.phaseFrame >= C.FLIGHT_FRAMES) {\n      s.z = 0; s.x = A.x1; s.y = A.y1;\n      if (Math.abs(s.x) > C.BOARD_HALF) return finish(s, 'F', 'side');\n      if (s.y > C.BOARD_BACK) return finish(s, 'F', 'long');\n      if (s.y < C.BOARD_FRONT) return finish(s, 'F', 'short');\n      const v = A.sp * C.ROLL_KEEP;\n      s.vx = v * Math.sin(A.ang); s.vy = v * Math.cos(A.ang);\n      s.phase = 'roll'; s.phaseFrame = 0;\n      s.event = { type: 'land' };\n    }\n    return;\n  }\n  if (s.phase === 'roll') {\n    s.x += s.vx * C.DT; s.y += s.vy * C.DT;\n    for (const p of L.pockets) {\n      const c = pocketAt(p, s.frame);\n      if (Math.hypot(s.x - c.x, s.y - c.y) < C.POCKET_R) { s.x = c.x; s.y = c.y; return finish(s, 'HR'); }\n    }\n    if (Math.abs(s.x) > C.BOARD_HALF) return finish(s, 'F', 'side');\n    if (s.y > C.BOARD_BACK) return finish(s, 'F', 'long');\n    if (decel(s, C.BOARD_FRICTION) > 0) return;\n    /* At rest. A ball sitting on a ring line hops one way or the other,\n       decided by this ball's own seeded draw. */\n    const dx = s.x - L.ring.x, dy = s.y - L.ring.y, d = Math.hypot(dx, dy) || 1;\n    for (const r of L.ring.r) {\n      if (Math.abs(d - r) < C.EDGE_BAND) {\n        const nd = s.air.hop < 0.5 ? r - C.HOP : r + C.HOP;\n        s.x = L.ring.x + dx / d * nd; s.y = L.ring.y + dy / d * nd;\n        break;\n      }\n    }\n    return finish(s, ringZone(L, s.x, s.y));\n  }\n  if (s.phase === 'settle') {\n    if (s.phaseFrame >= C.SETTLE_FRAMES) {\n      s.ball++;\n      s.x = 0; s.y = 0; s.z = 0; s.air = null;\n      if (s.ball >= C.BALLS) { s.over = true; s.phase = 'over'; s.event = { type: 'over' }; }\n      else { s.phase = 'ready'; s.phaseFrame = 0; }\n    }\n    return;\n  }\n  /* 'ready' and 'over' only tick the clock (a sliding pocket keeps moving). */\n}\n\n/* The per-game breakdown the server stores. */\nexport function detail(s) {\n  const zones = new Set(s.results.map(r => r.zone));\n  const cycle = ['1B', '2B', '3B', 'HR'].every(z => zones.has(z));\n  return { results: s.results.map(r => ({ zone: r.zone, bases: r.bases, hot: r.hot })), cycle, layout: s.day.layoutId, hot: s.day.hot };\n}\n\nexport function gems(score) { return gemsFor(score, C.GEM_BANDS); }\n\nconst SQ = { '1B': '🟩', '2B': '🟨', '3B': '🟧', HR: '🟥', F: '⬛' };\nexport function squares(d) { return d.results.map(r => SQ[r.zone]); }\nexport function scoreText(score) { return score + '/' + (C.BALLS * C.MAX_BASES); }\n\n/* Replay a whole run from its log. The server's only source of truth. */\nexport function replay(seed, inputs) {\n  if (!Array.isArray(inputs) || inputs.length !== C.BALLS) return { error: 'bad_inputs' };\n  const s = create(seed);\n  let i = 0, last = -1;\n  for (const inp of inputs) {\n    if (!inp || !Number.isInteger(inp.f) || inp.f < 0 || inp.f <= last || inp.f > C.MAX_FRAMES) return { error: 'bad_inputs' };\n    last = inp.f;\n  }\n  while (!s.over) {\n    if (s.frame > C.MAX_FRAMES) return { error: 'too_long' };\n    if (i < inputs.length && inputs[i].f === s.frame) {\n      if (!throwBall(s, inputs[i].a, inputs[i].p)) return { error: 'illegal_input', at: i };\n      i++;\n    } else if (s.phase === 'ready' && (i >= inputs.length || inputs[i].f < s.frame)) {\n      return { error: 'illegal_input', at: i };\n    }\n    step(s);\n  }\n  if (i !== inputs.length) return { error: 'illegal_input', at: i };\n  return { score: s.score, detail: detail(s), frames: s.frame };\n}\n","games/rollball/client.js":"/* Roll-Ball in the browser: input, a fixed-step loop, drawing and the screens.\n * The rules are sim.js, the same file the server replays. This file only\n * decides when a throw happens and records it as { f, a, p }. */\nimport { CONFIG as C } from './config.js';\nimport * as S from './sim.js';\nimport { api, session, makeSound, makeHaptics, makeHost, share, countdown, reducedMotion } from '../../shared/kit.js';\nimport { shareText } from '../../shared/share.js';\nimport { dateKey, dayNumber } from '../../shared/seed.js';\n\nconst VERSION = 'rollball-1';\nconst $ = id => document.getElementById(id);\nconst DEBUG = /[?&]debug=1/.test(location.search);\nconst sound = makeSound(), haptics = makeHaptics(), host = makeHost($('host'));\nconst RM = reducedMotion();\n\nconst ZONE_NAME = { '1B': 'SINGLE', '2B': 'DOUBLE', '3B': 'TRIPLE', HR: 'HOME RUN', F: 'FOUL' };\nconst ZONE_COL = { '1B': '#22B07D', '2B': '#d9a51c', '3B': '#e07a2a', HR: '#E0533D', F: '#141414' };\n\n/* ---------- state ---------- */\nlet today = null;           // the server's answer to /today\nlet mode = 'daily';         // or 'practice'\nlet st = null;              // the sim\nlet prev = null;            // the sim's ball position one step ago, for interpolation\nlet log = [];\nlet running = false, paused = false, startedAt = 0, finishing = false;\nlet pending = null;         // a throw waiting for the next step\nlet aim = null;             // { a, p, from } while aiming\nlet keys = { left: false, right: false, charging: false, chargeT: 0 };\nlet keyAngle = 0;\nlet fps = 0;\n\n/* ---------- canvas and projection ---------- */\nconst cv = $('c'), cx = cv.getContext('2d'), stage = $('stage');\nlet W = 0, H = 0, DPR = 1, KX = 1, KY = 1, BOTTOM = 0, OFFX = 0, boardImg = null;\nconst FAR = 345;\nconst sOf = y => 1 - 0.36 * Math.max(0, Math.min(1, y / FAR));\n/* The lane is foreshortened harder than the board, so the board (where the\n   scoring happens) gets most of the screen. */\nconst proj = y => y < C.LIP_Y ? y * 0.62 : C.LIP_Y * 0.62 + (y - C.LIP_Y) * 1.02;\nfunction SX(x, y) { return OFFX + W / 2 + x * KX * sOf(y); }\nfunction SY(y) { return BOTTOM - proj(y) * KY; }\n\nfunction resize() {\n  const r = $('stage').getBoundingClientRect();\n  DPR = Math.min(2, window.devicePixelRatio || 1);\n  W = Math.max(1, Math.round(r.width)); H = Math.max(1, Math.round(r.height));\n  cv.width = W * DPR; cv.height = H * DPR;\n  const w = Math.min(W, H * 0.7); OFFX = 0;\n  KX = (w * 0.47) / ((C.BOARD_HALF + 8) * sOf(C.BOARD_FRONT));\n  BOTTOM = H * 0.9;\n  KY = (H * 0.84) / proj(FAR);\n  boardImg = null;\n}\n\nfunction circlePts(cx0, cy0, r, n = 56) {\n  const pts = [];\n  for (let i = 0; i < n; i++) { const t = i / n * Math.PI * 2; const x = cx0 + r * Math.cos(t), y = cy0 + r * Math.sin(t); pts.push([SX(x, y), SY(y)]); }\n  return pts;\n}\nfunction poly(ctx, pts) { ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath(); }\n\n/* The static part of the playfield, drawn once per size. */\nfunction drawBoard() {\n  const off = document.createElement('canvas'); off.width = W * DPR; off.height = H * DPR;\n  const g = off.getContext('2d'); g.scale(DPR, DPR);\n  const L = st.layout;\n  // side gutters and the cabinet\n  g.fillStyle = '#d9d5cc';\n  poly(g, [[SX(-C.BOARD_HALF - 8, C.BOARD_FRONT - 8), SY(C.BOARD_FRONT - 8)], [SX(C.BOARD_HALF + 8, C.BOARD_FRONT - 8), SY(C.BOARD_FRONT - 8)],\n    [SX(C.BOARD_HALF + 8, C.BOARD_BACK + 6), SY(C.BOARD_BACK + 6)], [SX(-C.BOARD_HALF - 8, C.BOARD_BACK + 6), SY(C.BOARD_BACK + 6)]]); g.fill();\n  // the board\n  g.fillStyle = '#20231f';\n  poly(g, [[SX(-C.BOARD_HALF, C.BOARD_FRONT), SY(C.BOARD_FRONT)], [SX(C.BOARD_HALF, C.BOARD_FRONT), SY(C.BOARD_FRONT)],\n    [SX(C.BOARD_HALF, C.BOARD_BACK), SY(C.BOARD_BACK)], [SX(-C.BOARD_HALF, C.BOARD_BACK), SY(C.BOARD_BACK)]]); g.fill();\n  // the lane\n  const lane = g.createLinearGradient(0, SY(0), 0, SY(C.LIP_Y));\n  lane.addColorStop(0, '#c99a62'); lane.addColorStop(1, '#a87a46');\n  g.fillStyle = lane;\n  poly(g, [[SX(-C.LANE_HALF - 3, -14), SY(-14)], [SX(C.LANE_HALF + 3, -14), SY(-14)], [SX(C.LANE_HALF + 3, C.LIP_Y), SY(C.LIP_Y)], [SX(-C.LANE_HALF - 3, C.LIP_Y), SY(C.LIP_Y)]]); g.fill();\n  g.strokeStyle = 'rgba(0,0,0,.08)'; g.lineWidth = 1;\n  for (let x = -C.LANE_HALF + 7; x < C.LANE_HALF; x += 7) { g.beginPath(); g.moveTo(SX(x, -14), SY(-14)); g.lineTo(SX(x, C.LIP_Y), SY(C.LIP_Y)); g.stroke(); }\n  // rails\n  g.fillStyle = '#141414';\n  for (const sgn of [-1, 1]) {\n    poly(g, [[SX(sgn * (C.LANE_HALF + 3), -14), SY(-14)], [SX(sgn * (C.LANE_HALF + 7), -14), SY(-14)], [SX(sgn * (C.LANE_HALF + 7), C.LIP_Y), SY(C.LIP_Y)], [SX(sgn * (C.LANE_HALF + 3), C.LIP_Y), SY(C.LIP_Y)]]);\n    g.fill();\n  }\n  // the ramp up to the board\n  g.fillStyle = '#3a3a36';\n  poly(g, [[SX(-C.LANE_HALF - 7, C.LIP_Y), SY(C.LIP_Y)], [SX(C.LANE_HALF + 7, C.LIP_Y), SY(C.LIP_Y)],\n    [SX(C.BOARD_HALF, C.BOARD_FRONT), SY(C.BOARD_FRONT)], [SX(-C.BOARD_HALF, C.BOARD_FRONT), SY(C.BOARD_FRONT)]]); g.fill();\n  // the ramp lip\n  g.fillStyle = '#E0533D';\n  poly(g, [[SX(-C.LANE_HALF - 7, C.LIP_Y), SY(C.LIP_Y)], [SX(C.LANE_HALF + 7, C.LIP_Y), SY(C.LIP_Y)], [SX(C.LANE_HALF + 7, C.LIP_Y + 4), SY(C.LIP_Y + 4)], [SX(-C.LANE_HALF - 7, C.LIP_Y + 4), SY(C.LIP_Y + 4)]]); g.fill();\n  // the rings, outside in\n  const fills = { '1B': '#1d7f5c', '2B': '#a77d12', '3B': '#b45a19' };\n  const zones = ['1B', '2B', '3B'];\n  L.ring.r.forEach((r, i) => {\n    const z = zones[i];\n    poly(g, circlePts(L.ring.x, L.ring.y, r)); g.fillStyle = fills[z]; g.fill();\n    g.lineWidth = z === st.day.hot ? 3.5 : 2; g.strokeStyle = z === st.day.hot ? '#ffe680' : 'rgba(255,255,255,.75)'; g.stroke();\n  });\n  // ring labels\n  g.fillStyle = 'rgba(255,255,255,.92)'; g.textAlign = 'center'; g.textBaseline = 'middle';\n  const lbl = (t, x, y, sz) => { g.font = '800 ' + Math.round(sz * sOf(y)) + 'px Outfit, sans-serif'; g.fillText(t, SX(x, y), SY(y)); };\n  const [r1, r2] = L.ring.r;\n  lbl('1B', L.ring.x, L.ring.y - (r1 + r2) / 2, 13); lbl('2B', L.ring.x, L.ring.y - (r2 + L.ring.r[2]) / 2, 12); lbl('3B', L.ring.x, L.ring.y, 11);\n  if (st.day.hot) {\n    const yy = st.day.hot === '1B' ? L.ring.y + (r1 + r2) / 2 : st.day.hot === '2B' ? L.ring.y + (r2 + L.ring.r[2]) / 2 : L.ring.y + L.ring.r[2] + 4;\n    g.fillStyle = '#ffe680'; lbl('HOT +1', L.ring.x, Math.min(yy, L.ring.y + r1 - 4), 10);\n  }\n  boardImg = off;\n}\n\nfunction drawPockets(frame) {\n  for (const p of st.layout.pockets) {\n    const c = S.pocketAt(p, frame);\n    poly(cx, circlePts(c.x, c.y, C.POCKET_R + 2.5, 32)); cx.fillStyle = '#E0533D'; cx.fill();\n    poly(cx, circlePts(c.x, c.y, C.POCKET_R, 32)); cx.fillStyle = '#0b0b0b'; cx.fill();\n    cx.fillStyle = '#fff'; cx.font = '800 ' + Math.round(10 * sOf(c.y)) + 'px Outfit, sans-serif';\n    cx.textAlign = 'center'; cx.textBaseline = 'middle';\n    cx.fillText('HR', SX(c.x, c.y + C.POCKET_R + 7), SY(c.y + C.POCKET_R + 7));\n    if (p.slide && !RM) {\n      cx.strokeStyle = 'rgba(224,83,61,.35)'; cx.lineWidth = 1.5; cx.setLineDash([3, 4]);\n      cx.beginPath(); cx.moveTo(SX(p.x - p.slide.amp, p.y), SY(p.y)); cx.lineTo(SX(p.x + p.slide.amp, p.y), SY(p.y)); cx.stroke(); cx.setLineDash([]);\n    }\n  }\n}\n\nfunction drawBall(x, y, z) {\n  const s = sOf(y), r = 3.6 * KX * s;\n  // shadow on the surface, the ball lifted by its height\n  cx.fillStyle = 'rgba(0,0,0,.25)';\n  cx.beginPath(); cx.ellipse(SX(x, y), SY(y) + r * 0.4, r * 1.05, r * 0.45, 0, 0, Math.PI * 2); cx.fill();\n  const bx = SX(x, y), by = SY(y) - z * KY * 0.9 * s;\n  const gr = cx.createRadialGradient(bx - r * 0.35, by - r * 0.4, r * 0.2, bx, by, r);\n  gr.addColorStop(0, '#fff'); gr.addColorStop(1, '#c9c5bb');\n  cx.fillStyle = gr; cx.beginPath(); cx.arc(bx, by, r, 0, Math.PI * 2); cx.fill();\n  cx.strokeStyle = '#141414'; cx.lineWidth = 1.2; cx.stroke();\n}\n\nfunction drawAim() {\n  const a = aim ? aim.a : keyAngle, p = aim ? aim.p : keys.chargeT;\n  if (!aim && !keys.charging && !(st.phase === 'ready' && (keys.left || keys.right))) return;\n  // a faint guide up the lane, longer with more power\n  const len = 40 + p * (C.LIP_Y - 30);\n  cx.fillStyle = 'rgba(20,20,20,.55)';\n  for (let d = 10; d < len; d += 9) {\n    const x = d * Math.sin(a), y = d * Math.cos(a);\n    if (Math.abs(x) > C.LANE_HALF) break;\n    cx.beginPath(); cx.arc(SX(x, y), SY(y), 2.1 * sOf(y), 0, Math.PI * 2); cx.fill();\n  }\n  // the power meter\n  const mx = W - 22, mh = H * 0.32, my = BOTTOM - mh;\n  cx.fillStyle = 'rgba(20,20,20,.12)'; cx.fillRect(mx, my, 12, mh);\n  cx.fillStyle = p > 0.85 ? '#E0533D' : '#22B07D'; cx.fillRect(mx, my + mh * (1 - p), 12, mh * p);\n  cx.strokeStyle = '#141414'; cx.lineWidth = 1.5; cx.strokeRect(mx, my, 12, mh);\n}\n\nfunction drawDebug(alpha) {\n  const L = st.layout;\n  cx.strokeStyle = '#0f0'; cx.lineWidth = 1;\n  for (const r of L.ring.r) { poly(cx, circlePts(L.ring.x, L.ring.y, r)); cx.stroke(); }\n  for (const p of L.pockets) { const c = S.pocketAt(p, st.frame); poly(cx, circlePts(c.x, c.y, C.POCKET_R, 24)); cx.stroke(); }\n  cx.beginPath(); cx.moveTo(SX(-C.LANE_HALF, 0), SY(0)); cx.lineTo(SX(-C.LANE_HALF, C.LIP_Y), SY(C.LIP_Y));\n  cx.moveTo(SX(C.LANE_HALF, 0), SY(0)); cx.lineTo(SX(C.LANE_HALF, C.LIP_Y), SY(C.LIP_Y)); cx.stroke();\n  let d = $('dbg'); if (!d) { d = document.createElement('div'); d.id = 'dbg'; d.className = 'dbg'; $('stage').appendChild(d); }\n  d.textContent = 'fps ' + fps.toFixed(0) + '  seed ' + st.seed + '\\nlayout ' + L.id + '  hot ' + st.day.hot +\n    '\\nframe ' + st.frame + '  phase ' + st.phase + '  a ' + alpha.toFixed(2) +\n    '\\nV ' + C.V_MIN + '..' + C.V_MAX + '  carry ' + C.CARRY_S + '  jit ' + C.CARRY_JITTER +\n    '\\nball ' + st.x.toFixed(1) + ',' + st.y.toFixed(1) + ' z' + st.z.toFixed(1);\n}\n\nfunction render(alpha) {\n  cx.setTransform(DPR, 0, 0, DPR, 0, 0);\n  cx.fillStyle = '#EFEDE8'; cx.fillRect(0, 0, W, H);\n  if (!st) return;\n  if (!boardImg) drawBoard();\n  cx.drawImage(boardImg, 0, 0, W, H);\n  drawPockets(st.frame);\n  const ix = prev ? prev.x + (st.x - prev.x) * alpha : st.x;\n  const iy = prev ? prev.y + (st.y - prev.y) * alpha : st.y;\n  const iz = prev ? prev.z + (st.z - prev.z) * alpha : st.z;\n  if (st.phase !== 'over') drawBall(ix, iy, iz);\n  if (st.phase === 'ready') drawAim();\n  if (DEBUG) drawDebug(alpha);\n}\n\n/* ---------- the loop ---------- */\nlet last = 0, acc = 0, fpsT = 0, fpsN = 0;\nfunction frame(ts) {\n  requestAnimationFrame(frame);\n  if (!last) last = ts;\n  let dt = Math.min(0.25, (ts - last) / 1000); last = ts;\n  fpsN++; fpsT += dt; if (fpsT >= 0.5) { fps = fpsN / fpsT; fpsN = 0; fpsT = 0; }\n  if (running && !paused && st && !st.over) {\n    acc += dt;\n    while (acc >= C.DT) { tick(); acc -= C.DT; if (!running) break; }\n  }\n  render(running ? acc / C.DT : 1);\n}\n\nfunction tick() {\n  // the keyboard charges a throw a step at a time, so it is frame-exact too\n  if (st.phase === 'ready') {\n    if (keys.left) keyAngle = Math.max(-C.MAX_ANGLE, keyAngle - 0.006);\n    if (keys.right) keyAngle = Math.min(C.MAX_ANGLE, keyAngle + 0.006);\n    if (keys.charging) keys.chargeT = Math.min(1, keys.chargeT + C.DT / 1.3);\n  }\n  if (pending && st.phase === 'ready') {\n    const f = st.frame;\n    if (S.throwBall(st, pending.a, pending.p)) { log.push({ f, a: pending.a, p: pending.p }); onThrow(); }\n    pending = null;\n  }\n  prev = { x: st.x, y: st.y, z: st.z };\n  const ball = st.ball;\n  S.step(st);\n  if (st.event) onEvent(st.event);\n  if (stage.dataset.phase !== st.phase) stage.dataset.phase = st.phase;\n  if (st.ball !== ball && !st.over) { hud(); prev = null; host.set(st.ball >= 7 ? 'nervous' : 'idle', 'ready'); }\n}\n\nfunction round4(v) { return Math.round(v * 10000) / 10000; }\nfunction queueThrow(a, p) {\n  if (!running || paused || st.phase !== 'ready' || pending) return;\n  pending = { a: round4(Math.max(-C.MAX_ANGLE, Math.min(C.MAX_ANGLE, a))), p: round4(Math.max(0, Math.min(1, p))) };\n}\n\nfunction onThrow() {\n  sound.play('roll'); haptics.buzz(12);\n  $('hint').textContent = '';\n  host.set(st.ball >= 7 ? 'nervous' : 'idle', 'watching');\n}\n\nfunction onEvent(e) {\n  if (e.type === 'launch') sound.play('launch');\n  else if (e.type === 'land') { sound.play('land'); haptics.buzz(20); }\n  else if (e.type === 'rail') sound.play('rail');\n  else if (e.type === 'result') {\n    const pop = $('pop');\n    pop.textContent = ZONE_NAME[e.zone] + (e.hot ? ' +1' : '');\n    pop.style.background = ZONE_COL[e.zone];\n    pop.classList.remove('on'); void pop.offsetWidth; pop.classList.add('on');\n    if (e.zone === 'HR') { sound.play('big'); haptics.buzz([30, 40, 60]); host.set('hype', 'homer'); }\n    else if (e.zone === 'F') { sound.play('foul'); host.set('disappointed', 'foul'); }\n    else { sound.play('good'); host.set(e.zone === '3B' ? 'celebrate' : 'idle', 'hit'); }\n    hud();\n  } else if (e.type === 'over') finish();\n}\n\n/* ---------- HUD ---------- */\nfunction hud() {\n  $('hBases').textContent = st.score;\n  $('hBall').textContent = Math.min(C.BALLS, st.ball + 1) + '/' + C.BALLS;\n  drawDiamond();\n}\n/* The bases as a mini diamond: each result lights the bags it reached. */\nfunction drawDiamond() {\n  const svg = $('diamond');\n  const last = st.results[st.results.length - 1];\n  const reached = last ? last.bases : 0;\n  const pts = [[26, 46], [46, 26], [26, 6], [6, 26]];\n  let s = '<path d=\"M26 46 L46 26 L26 6 L6 26 Z\" fill=\"none\" stroke=\"#141414\" stroke-width=\"2\"/>';\n  pts.forEach((p, i) => {\n    const lit = i === 0 ? reached >= 4 : reached >= i;\n    s += '<rect x=\"' + (p[0] - 5) + '\" y=\"' + (p[1] - 5) + '\" width=\"10\" height=\"10\" transform=\"rotate(45 ' + p[0] + ' ' + p[1] + ')\" fill=\"' +\n      (lit ? (reached >= 4 ? '#E0533D' : '#22B07D') : '#fff') + '\" stroke=\"#141414\" stroke-width=\"1.5\"/>';\n  });\n  svg.innerHTML = s;\n}\n\n/* ---------- input ---------- */\n/* Full power is this far a pull: whatever room the lane leaves below its top. */\nconst PULL_FULL = () => Math.max(120, Math.min(H * 0.26, H - SY(C.LIP_Y) - 20));\nfunction stagePt(e) { const r = cv.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }\ncv.addEventListener('pointerdown', e => {\n  sound.unlock();\n  if (!running || paused || !st || st.phase !== 'ready' || pending) return;\n  const p = stagePt(e);\n  // forgiving: a drag can start anywhere on the lane, so a thumb has room to\n  // pull back even though the ball sits near the bottom of the screen\n  if (p.y < SY(C.LIP_Y) - 30) return;\n  cv.setPointerCapture(e.pointerId);\n  aim = { from: p, a: 0, p: 0 };\n  e.preventDefault();\n});\ncv.addEventListener('pointermove', e => {\n  if (!aim) return;\n  const p = stagePt(e), dx = p.x - aim.from.x, dy = p.y - aim.from.y;\n  const pull = Math.max(0, dy);\n  aim.p = Math.max(0, Math.min(1, pull / PULL_FULL()));\n  // a slingshot: pull back and to the left to roll right\n  aim.a = Math.max(-C.MAX_ANGLE, Math.min(C.MAX_ANGLE, Math.atan2(-dx, Math.max(30, pull)) * 0.9));\n});\nfunction release() {\n  if (!aim) return;\n  const a = aim; aim = null;\n  if (a.p < 0.04) return;   // a tap is not a throw\n  queueThrow(a.a, a.p);\n}\ncv.addEventListener('pointerup', release);\ncv.addEventListener('pointercancel', () => { aim = null; });\n\naddEventListener('keydown', e => {\n  if (!running || paused) return;\n  if (e.key === 'ArrowLeft') { keys.left = true; e.preventDefault(); }\n  else if (e.key === 'ArrowRight') { keys.right = true; e.preventDefault(); }\n  else if (e.key === ' ' && !e.repeat) { sound.unlock(); keys.charging = true; keys.chargeT = 0; e.preventDefault(); }\n});\naddEventListener('keyup', e => {\n  if (e.key === 'ArrowLeft') keys.left = false;\n  else if (e.key === 'ArrowRight') keys.right = false;\n  else if (e.key === ' ' && keys.charging) { keys.charging = false; if (keys.chargeT >= 0.04) queueThrow(keyAngle, keys.chargeT); keys.chargeT = 0; e.preventDefault(); }\n});\n\n/* Pause when the tab is left. */\nfunction pause() { if (running && !st.over) { paused = true; aim = null; keys.charging = false; $('pause').classList.add('on'); } }\nfunction resume() { paused = false; last = 0; $('pause').classList.remove('on'); }\ndocument.addEventListener('visibilitychange', () => { if (document.hidden) pause(); });\naddEventListener('blur', pause);\n$('pause').addEventListener('click', resume);\n$('pause').addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') resume(); });\n\n/* Never lose a run to a back swipe. */\nfunction midRun() { return running && st && !st.over && log.length > 0; }\naddEventListener('beforeunload', e => { if (midRun()) { e.preventDefault(); e.returnValue = ''; } });\naddEventListener('popstate', () => {\n  if (midRun() && !confirm('Leave this run? It will not count.')) { history.pushState({ rb: 1 }, ''); return; }\n  location.href = '/arcade/';\n});\n$('back').addEventListener('click', e => { if (midRun() && !confirm('Leave this run? It will not count.')) e.preventDefault(); });\n\n$('mute').setAttribute('aria-pressed', String(sound.muted));\n$('mute').addEventListener('click', () => { sound.unlock(); $('mute').setAttribute('aria-pressed', String(sound.toggle())); });\n\n/* ---------- screens ---------- */\nfunction sheet(html) { $('card').innerHTML = html; $('sheet').classList.add('on'); }\nfunction closeSheet() { $('sheet').classList.remove('on'); }\n\nfunction intro() {\n  host.set('idle');\n  const played = today && today.played;\n  const rule = today ? today.config.rule : S.dailyConfig(st.seed).rule;\n  sheet('<h2>Roll-Ball' + (today ? ' <span class=\"mut\">#' + today.dayNumber + '</span>' : '') + '</h2>' +\n    '<p class=\"rule\">Roll nine balls. Land them in the rings. Rack up bases.</p>' +\n    '<p class=\"today\">Today: ' + esc(rule) + '</p>' +\n    '<p class=\"mut\">Touch the lane, pull back and let go. Pull further for more power, sideways to aim. Keyboard: arrows aim, hold Space to charge.</p>' +\n    '<div class=\"row\">' + (played ? '<button class=\"btn\" id=\"bSeen\">See today\\'s result</button>' : '<button class=\"btn go\" id=\"bPlay\">Play today</button>') +\n    '<button class=\"btn alt\" id=\"bPrac\">Practice</button></div>' +\n    '<label class=\"toggle\"><input type=\"checkbox\" id=\"hap\"' + (haptics.on ? ' checked' : '') + '> Vibrate on hits</label>');\n  if ($('bPlay')) $('bPlay').onclick = () => start('daily');\n  if ($('bSeen')) $('bSeen').onclick = () => showResult(today.played, true);\n  $('bPrac').onclick = () => start('practice');\n  $('hap').onchange = () => haptics.toggle();\n}\n\nfunction start(m) {\n  sound.unlock();\n  mode = m;\n  const seed = m === 'daily' ? today.seed : crypto.getRandomValues(new Uint32Array(1))[0];\n  st = S.create(seed); prev = null; log = []; pending = null; aim = null; keyAngle = 0; finishing = false;\n  boardImg = null; running = true; paused = false; acc = 0; last = 0; startedAt = performance.now();\n  $('pchip').hidden = m !== 'practice';\n  closeSheet(); hud();\n  $('hint').textContent = 'Touch the lane, pull back, let go';\n  history.pushState({ rb: 1 }, '');\n}\n\nasync function finish() {\n  if (finishing) return; finishing = true; running = false;\n  const durationMs = Math.round(performance.now() - startedAt);\n  const local = { score: st.score, scoreText: S.scoreText(st.score), detail: S.detail(st), squares: S.squares(S.detail(st)),\n    gems: 0, dayNumber: today ? today.dayNumber : dayNumber(dateKey(Date.now())) };\n  host.set(st.score >= 24 ? 'celebrate' : st.score <= 11 ? 'disappointed' : 'idle', 'over');\n  if (mode !== 'daily') return showResult(local, false, 'Practice run. Not scored and no gems.');\n  sheet('<h2>Checking the board...</h2>');\n  const r = await api('POST', 'roll-ball/run', { mode: 'daily', dateKey: today.dateKey, seed: today.seed, inputs: log,\n    score: st.score, durationMs, clientVersion: VERSION }).catch(() => ({ status: 0 }));\n  if (r.status === 200) { today.played = r.data.result; showResult(r.data.result, true, null, r.data.gems); }\n  else showResult(local, false, r.status === 409 ? 'You already played today.' :\n    'This run did not save (' + ((r.data && r.data.error) || 'network') + '). Nothing was scored.', null, r.status === 0);\n}\n\nasync function showResult(res, saved, note, total, retry) {\n  running = false;\n  const d = res.detail;\n  const text = shareText('Roll-Ball', res.dayNumber, res.scoreText || S.scoreText(res.score), res.squares || S.squares(d));\n  sheet('<h2>' + (saved ? 'Today\\'s run' : mode === 'practice' ? 'Practice' : 'Run over') + '</h2>' +\n    '<div class=\"score\">' + esc(res.scoreText || S.scoreText(res.score)) + '</div><div class=\"mut\">bases</div>' +\n    '<div class=\"strip\" aria-label=\"Ball by ball\">' + (res.squares || S.squares(d)).join('') + '</div>' +\n    (d && d.cycle ? '<p>Hit for the cycle<span class=\"badge\">CYCLE</span></p>' : '') +\n    (saved ? '<p class=\"gems\">+' + res.gems + ' gems' + (total != null ? ' <span class=\"mut\">(' + total + ' total)</span>' : '') + '</p>' +\n      '<p class=\"mut\">Gems are just for fun. They have no cash value.</p>' : '') +\n    (note ? '<p class=\"mut\">' + esc(note) + '</p>' : '') +\n    '<div class=\"row\">' + (saved ? '<button class=\"btn go\" id=\"bShare\">Share</button>' : '') +\n    (retry ? '<button class=\"btn\" id=\"bRetry\">Try saving again</button>' : '') +\n    '<button class=\"btn alt\" id=\"bPrac\">Practice</button></div>' +\n    '<p class=\"mut\">Next daily in <b id=\"cd\"></b></p><div class=\"board\" id=\"lb\"></div>');\n  if ($('bShare')) $('bShare').onclick = async () => { const s = await share(text); $('bShare').textContent = s === 'copied' ? 'Copied' : 'Share'; };\n  if ($('bRetry')) $('bRetry').onclick = () => { finishing = false; finish(); };\n  $('bPrac').onclick = () => start('practice');\n  countdown($('cd'));\n  if (saved) loadBoard();\n}\n\nasync function loadBoard() {\n  const r = await api('GET', 'roll-ball/leaderboard').catch(() => null);\n  if (!r || r.status !== 200 || !$('lb')) return;\n  const b = r.data;\n  $('lb').innerHTML = '<b>Today\\'s board</b> <span class=\"mut\">(' + b.total + ' played)</span>' +\n    (b.top.length ? '<ol>' + b.top.slice(0, 10).map(x => '<li' + (x.me ? ' class=\"me\"' : '') + '>' + esc(x.name) + ' <span class=\"mut\">' + x.score + '</span></li>').join('') + '</ol>'\n      : '<p class=\"mut\">Sign in to put your name on the board.</p>') +\n    (b.me && b.me.rank ? '<p class=\"mut\">You are #' + b.me.rank + '.</p>' : '');\n}\n\nfunction esc(s) { return String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c])); }\n\n/* ---------- boot ---------- */\nasync function boot() {\n  resize(); addEventListener('resize', resize);\n  requestAnimationFrame(frame);\n  sheet('<h2>Roll-Ball</h2><p class=\"mut\">Loading today\\'s board...</p>');\n  await session();\n  const r = await api('GET', 'roll-ball/today').catch(() => ({ status: 0 }));\n  if (r.status !== 200) { sheet('<h2>Roll-Ball</h2><p>Could not load today. <a href=\"/arcade/\">Back to the Arcade</a></p>'); return; }\n  today = r.data;\n  st = S.create(today.seed);\n  if (today.played) { mode = 'daily'; showResult(today.played, true, null, today.gems); return; }\n  intro();\n}\nboot();\n"};
